    <style>
        :root{--bg:#f5f7fb;--surface:#fff;--ink:#0f172a;--muted:#64748b;--line:#e7eaf0;--dark:#0b1020;--accent:#6d5dfc;--accent2:#8b7cff;--soft:#f3f1ff;--shadow:0 18px 60px rgba(15,23,42,.08)}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 90% 0%,rgba(109,93,252,.08),transparent 28%),var(--bg);color:var(--ink);font-family:Tahoma,Arial,sans-serif;-webkit-font-smoothing:antialiased}.container{width:min(1180px,92%);margin:auto}a{text-decoration:none;color:inherit}.nav{position:sticky;top:0;z-index:50;background:rgba(11,16,32,.88);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08)}.navin{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:12px;color:#fff;font-size:22px;font-weight:900;letter-spacing:-.5px}.brandmark{width:38px;height:38px;border-radius:13px;background:linear-gradient(135deg,var(--accent),#23c6d9);display:grid;place-items:center;box-shadow:0 10px 30px rgba(109,93,252,.35);font-weight:900}.navlinks{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.navlinks a,.navlinks button{color:#cbd5e1;padding:10px 13px;border-radius:12px;background:transparent;border:0;font:inherit;cursor:pointer;transition:.2s}.navlinks a:hover,.navlinks button:hover{background:rgba(255,255,255,.08);color:#fff}.wallet-pill{padding:10px 14px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.05);border-radius:999px;color:#fff;font-size:13px}.hero{padding:46px 0 24px}.hero-box{position:relative;overflow:hidden;border-radius:34px;padding:64px;min-height:400px;background:linear-gradient(135deg,#0b1020 0%,#161d36 52%,#282060 100%);box-shadow:0 30px 90px rgba(11,16,32,.2);color:#fff}.hero-box:before,.hero-box:after{content:"";position:absolute;border-radius:50%;pointer-events:none}.hero-box:before{width:380px;height:380px;background:radial-gradient(circle,rgba(109,93,252,.34),transparent 70%);top:-130px;left:-90px}.hero-box:after{width:320px;height:320px;background:radial-gradient(circle,rgba(35,198,217,.2),transparent 70%);bottom:-120px;right:4%}.eyebrow{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.05);border-radius:999px;color:#cbd5e1;font-size:13px}.hero h1{position:relative;z-index:1;font-size:clamp(36px,5vw,62px);line-height:1.12;letter-spacing:-1.7px;margin:20px 0 16px;max-width:760px}.hero p{position:relative;z-index:1;color:#cbd5e1;line-height:2;font-size:17px;max-width:700px;margin:0 0 28px}.hero-actions{position:relative;z-index:2;display:flex;gap:12px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 18px;min-height:46px;border-radius:14px;font-weight:800;border:1px solid transparent;cursor:pointer;transition:transform .18s,box-shadow .18s,background .18s}.btn:hover{transform:translateY(-2px)}.btn-primary{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;box-shadow:0 14px 28px rgba(109,93,252,.28)}.btn-light{background:#fff;color:#111827}.btn-dark{background:var(--dark);color:#fff;box-shadow:0 10px 24px rgba(15,23,42,.12)}.btn-soft{background:var(--soft);color:#5b4ee5;border-color:#e4e0ff}.section{padding:26px 0 46px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:20px}.section-head h2{margin:0;font-size:25px;letter-spacing:-.5px}.section-head p,.muted{color:var(--muted);font-size:14px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.card{background:rgba(255,255,255,.9);border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:var(--shadow);transition:transform .2s,box-shadow .2s,border-color .2s}.card:hover{transform:translateY(-4px);box-shadow:0 24px 60px rgba(15,23,42,.1);border-color:#dddff0}.cat{min-height:126px;display:flex;flex-direction:column;justify-content:flex-end;background:linear-gradient(180deg,#fff,#f8f7ff)}.cat-icon{width:48px;height:48px;border-radius:15px;background:var(--soft);color:#6355e8;display:grid;place-items:center;font-size:22px;margin-bottom:auto}.cat-title{font-weight:900;font-size:17px}.product{display:flex;flex-direction:column;gap:12px;overflow:hidden}.product-img{height:190px;background:linear-gradient(135deg,#f0efff,#eef8fb);border-radius:17px;display:flex;align-items:center;justify-content:center;color:#a0a7b8;overflow:hidden;position:relative}.product-img img{width:100%;height:100%;object-fit:cover}.product-meta{display:flex;justify-content:space-between;gap:12px;align-items:center}.badge{display:inline-flex;align-items:center;padding:6px 9px;border-radius:999px;background:#f5f6fa;color:#667085;font-size:12px;font-weight:700}.price-row{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap}.price{font-size:20px;font-weight:900;letter-spacing:-.3px}.old{font-size:13px;color:#94a3b8;text-decoration:line-through}.product-name{font-size:18px;font-weight:900}.flash{margin:18px 0;padding:15px 18px;border-radius:15px;background:#ecfdf5;color:#047857;border:1px solid #ccefe1}.errors{margin:18px 0;padding:15px 18px;border-radius:15px;background:#fff1f2;color:#be123c;border:1px solid #ffd6dc}.form-box{max-width:620px;margin:50px auto;background:rgba(255,255,255,.94);padding:34px;border-radius:26px;border:1px solid var(--line);box-shadow:var(--shadow)}.form-group{margin:0 0 17px}.form-group label{display:block;margin-bottom:8px;font-weight:800;font-size:14px}.form-group input,.form-group textarea,.form-group select{width:100%;padding:14px 15px;border:1px solid #dfe3eb;border-radius:13px;outline:none;background:#fff;font:inherit;transition:.2s}.form-group input:focus,.form-group textarea:focus,.form-group select:focus{border-color:#9d94ff;box-shadow:0 0 0 4px rgba(109,93,252,.08)}.footer{padding:46px 0;color:#94a3b8;text-align:center;font-size:13px}.empty{padding:34px;text-align:center;color:var(--muted);background:#fff;border-radius:20px;border:1px dashed #d8dce7}.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.stat{padding:22px}.stat .value{font-size:30px;font-weight:900;margin-top:8px}.cart-count{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;background:var(--accent);color:#fff;border-radius:999px;font-size:11px;margin-right:4px}@media(max-width:980px){.grid{grid-template-columns:repeat(2,1fr)}.hero-box{padding:48px}.stats-grid{grid-template-columns:1fr}}@media(max-width:620px){.container{width:min(94%,1180px)}.navin{padding:12px 0;align-items:flex-start;flex-direction:column}.navlinks{width:100%}.hero{padding-top:24px}.hero-box{padding:32px 24px;min-height:360px}.hero h1{font-size:37px}.grid{grid-template-columns:1fr}.section-head{align-items:flex-start;flex-direction:column}.form-box{padding:24px;margin-top:28px}}
    </style>
